  <div class="animate-in slide-in-from-bottom-full" tw-class="bg-white/95 dark:bg-gray-900/95 backdrop-blur-md border-t border-gray-100 dark:border-gray-800 shadow-2xl z-40 flex flex-col h-[70vh] min-h-[400px] overflow-visible duration-300">
