          :key="idToRaw({ id: group.messageId })"
          tw-class="flex flex-col gap-3 group/group relative hover:z-30"
        >
          <!-- Message Header: Jump Button & Shared Prompt -->
          <div tw-class="flex items-start justify-between gap-4">
            <div tw-class="flex-1 min-w-0">
              <div tw-class="flex items-center gap-2 mb-1">
