                  :title="lazyStrings.ChatMediaShelf__click_to_copy_prompt()"
                >
                  <div tw-class="text-[10px] font-bold text-gray-400 dark:text-gray-500 truncate italic hover:text-blue-500 transition-colors pr-8">
                    {{ group.prompt }}
                  </div>
                  <div tw-class="absolute right-0 top-1/2 -translate-y-1/2 opacity-0 group-hover/prompt:opacity-100 transition-opacity flex items-center gap-1 bg-white/80 dark:bg-gray-900/80 px-1 rounded shadow-sm">
                    <template v-if="copiedPromptId === group.messageId">
                      <CheckIcon tw-class="w-2.5 h-2.5 text-green-500" />
                      <span tw-class="text-[8px] font-bold text-green-500 uppercase">{{ lazyStrings.ChatMediaShelf__copied() }}</span>
                    </template>
                    <template v-else>
                      <CopyIcon tw-class="w-2.5 h-2.5 text-blue-500" />
                    </template>
                  </div>
                </div>
                <div v-else tw-class="text-[10px] font-bold text-gray-300 dark:text-gray-700 uppercase tracking-widest italic">
                  {{ lazyStrings.ChatMediaShelf__manual_attachment() }}
                </div>
              </div>
            </div>
          </div>

          <!-- Grouped Images (Horizontal Scroll) -->
          <!-- Use pb-32 to provide internal space for dropdowns, but -mb-28 to pull the next group up visually -->
          <div class="no-scrollbar" tw-class="flex items-center gap-4 overflow-x-auto pb-32 -mb-28 -mx-1 px-1">
            <div
              v-for="item in group.items"
              :key="item.id"
              :data-id="idToRaw({ id: item.binaryObjectId })"
              data-testid="media-preview-trigger" class="media-item-trigger" tw-class="relative w-36 h-36 shrink-0 group/item hover:z-40"
              @click="handlePreview({ item })"
            >
              <div tw-class="absolute inset-0 rounded-2xl border border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-800 shadow-sm hover:shadow-md hover:border-blue-500/50 transition-all overflow-hidden">
                <img
                  v-if="thumbnails.get(item.binaryObjectId)"
                  :src="thumbnails.get(item.binaryObjectId)"
                  tw-class="w-full h-full object-cover transition-transform group-hover/item:scale-110"
                />
                <div v-else tw-class="w-full h-full flex items-center justify-center">
                  <ImageIcon tw-class="w-8 h-8 text-gray-300 animate-pulse" />
                </div>

                <!-- Hover Gradient -->
                <div tw-class="absolute inset-0 bg-gradient-to-t from-black/20 via-transparent to-transparent opacity-0 group-hover/item:opacity-100 transition-opacity pointer-events-none"></div>
              </div>

              <!-- Item Overlay - Top Buttons -->
              <div tw-class="absolute top-2 right-2 z-50 flex flex-col gap-1.5 opacity-0 group-hover/item:opacity-100 transition-all origin-top-right overflow-visible">
                <div @click.stop>
                  <ImageDownloadButton
                    :is-supported="isSupportedMap.get(item.binaryObjectId)"
                    :on-download="({ withMetadata }: { withMetadata: boolean }) => handleDownload({ item, withMetadata })"
                    :align="item.index === 1 ? 'left' : 'right'"
                  />
                </div>
                <button
                  v-if="item.prompt || item.seed || item.steps"
                  tw-class="p-2 bg-white/90 dark:bg-gray-800/90 backdrop-blur-sm border border-gray-100 dark:border-gray-700 rounded-lg text-gray-500 hover:text-blue-600 shadow-sm transition-colors flex items-center justify-center"
                  :title="lazyStrings.ChatMediaShelf__view_details_and_copy_parameters()"
                  @click.stop="showingInfoId = item.id"
                >
                  <InfoIcon tw-class="w-4 h-4" />
                </button>
              </div>

              <!-- Info Details Overlay (Copyable) -->
              <div
                v-if="showingInfoId === item.id"
                class="animate-in fade-in zoom-in" tw-class="absolute inset-0 z-50 bg-white/95 dark:bg-gray-900/95 p-3 rounded-2xl border border-blue-200 dark:border-blue-800 flex flex-col gap-2 duration-200 shadow-xl"
                @click.stop
              >
                <div tw-class="flex items-center justify-between border-b dark:border-gray-800 pb-1.5 mb-1">
                  <span tw-class="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{{ lazyStrings.ChatMediaShelf__parameters() }}</span>
                  <button @click="showingInfoId = null" tw-class="p-1 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg text-gray-400 hover:text-red-500 transition-colors">
                    <XIcon tw-class="w-3.5 h-3.5" />
